mapper.select:
select tccpt.project_id as projectId, tccpt.monomer_id as monomerId, tccpt.area_id as areaId, tccpt.product_id as productId, tccpt.product_serial_number as productSerialNumber, tccpt.product_type as productType, COUNT(*) as productQuantity, CASE WHEN COUNT(DISTINCT tccpt.tech_capp_product_task_work_type) = 1 AND MAX(tccpt.tech_capp_product_task_work_type) = 1 THEN 1 WHEN COUNT(DISTINCT tccpt.tech_capp_product_task_work_type) = 1 AND MAX(tccpt.tech_capp_product_task_work_type) = 4 THEN 4 ELSE 2 END as techCappProductTaskWorkType from tech_capp_craft_product_task as tccpt
tccpt.bool_delete_enum = 0
and (tccpt.mes_building_task_id in
#{item}
or tccpt.mes_building_task_id = 0 )
and tccpt.tech_capp_product_task_work_type = #{dto.techCappProductTaskWorkType}
and tccpt.project_id = #{dto.projectId}
and tccpt.monomer_id = #{dto.monomerId}
and tccpt.area_id = #{dto.areaId}
and tccpt.product_serial_number like concat('%',#{dto.productSerialNumber},'%')
group by tccpt.project_id, tccpt.monomer_id, tccpt.area_id, tccpt.product_id, tccpt.product_serial_number, tccpt.product_type

select tccpt.id as id, tccpt.welding_serial_number as weldingSerialNumber, tccpt.product_serial_number as productSerialNumber, tcccs.welding_base_joint_type as weldingBaseJointType, tcccs.serial_number as techCappCraftCardStorehouseSerialNumber, tcccs.welding_base_welding_method as weldingBaseWeldingMethod, tccpt.tech_capp_product_task_work_type as techCappProductTaskWorkType from tech_capp_craft_product_weld_task as tccpt left join tech_capp_craft_card_storehouse as tcccs on tcccs.id = tccpt.tech_capp_craft_card_storehouse_id
tccpt.bool_delete_enum = 0 and tccpt.tech_capp_craft_product_task_id = #{id}
and tccpt.tech_capp_product_task_work_type = #{techCappProductTaskWorkType}
order by tccpt.tech_capp_product_task_work_type asc
